  /// If `nodes` contains non-`nil` values, construct a ``RawUnexpectedNodesSyntax``
  /// containing those tokens, otherwise return `nil`.
  init?<SyntaxType: RawSyntaxNodeProtocol>(_ nodes: [SyntaxType?], arena: __shared RawSyntaxArena) {
